/**
 * @file system_init.c
 * @brief System Startup / Initialisation implementation.
 *
 * Software Unit: System Startup/Initialization
 * Traces: SWE-REQ-020, SWE-REQ-021
 *
 * Platform: STM32F407G-DISC1 / STM32 HAL
 * No dynamic allocation (SWE-REQ-036).
 *
 * ASSUMPTIONS / CONFIGURATION NOTE:
 *   All peripheral configurations below (clock, GPIO, UART, ADC, TIM) are
 *   representative defaults for the STM32F407G-DISC1.  In a production
 *   project these would normally be generated by STM32CubeMX.  Pin
 *   assignments and clock values are PLACEHOLDERS – verify against the
 *   actual schematic and CubeMX .ioc before deployment.
 *
 *   UART2 : PA2 (TX), PA3 (RX) – connected to ST-LINK virtual COM port
 *   ADC1  : PA1 (Channel 1)    – potentiometer feedback
 *   TIM2  : PA0 (CH1 PWM)      – motor enable via L298N ENA
 *   Motor direction : PB0 (IN1), PB1 (IN2)
 *   LEDs  : PD12..PD15, PE0, PE1 (see led_status_handler.c)
 */

#include "system_init.h"

#include "command_parser.h"
#include "feedback_processor.h"
#include "flap_control_logic.h"
#include "motor_driver.h"
#include "led_status_handler.h"

#include "stm32f4xx_hal.h"
#include <stdbool.h>

/* ==================================================================
 *  HAL Handle Instances (global, used by other units via extern)
 * ================================================================== */

UART_HandleTypeDef huart2;
ADC_HandleTypeDef  hadc1;
TIM_HandleTypeDef  htim2;

/* ==================================================================
 *  Private: Clock Configuration
 * ================================================================== */

/**
 * @brief Configure system clocks (HSE → PLL → 168 MHz SYSCLK).
 *
 * Placeholder values for STM32F407 Discovery.
 */
static void SystemClock_Config(void)
{
    RCC_OscInitTypeDef RCC_OscInitStruct = {0};
    RCC_ClkInitTypeDef RCC_ClkInitStruct = {0};

    /** Supply configuration – use HSE (8 MHz crystal on Discovery) */
    RCC_OscInitStruct.OscillatorType = RCC_OSCILLATORTYPE_HSE;
    RCC_OscInitStruct.HSEState       = RCC_HSE_ON;
    RCC_OscInitStruct.PLL.PLLState   = RCC_PLL_ON;
    RCC_OscInitStruct.PLL.PLLSource  = RCC_PLLSOURCE_HSE;
    RCC_OscInitStruct.PLL.PLLM       = 8U;
    RCC_OscInitStruct.PLL.PLLN       = 336U;
    RCC_OscInitStruct.PLL.PLLP       = RCC_PLLP_DIV2;   /* 168 MHz */
    RCC_OscInitStruct.PLL.PLLQ       = 7U;
    (void)HAL_RCC_OscConfig(&RCC_OscInitStruct);

    RCC_ClkInitStruct.ClockType      = RCC_CLOCKTYPE_HCLK  | RCC_CLOCKTYPE_SYSCLK |
                                       RCC_CLOCKTYPE_PCLK1 | RCC_CLOCKTYPE_PCLK2;
    RCC_ClkInitStruct.SYSCLKSource   = RCC_SYSCLKSOURCE_PLLCLK;
    RCC_ClkInitStruct.AHBCLKDivider  = RCC_SYSCLK_DIV1;
    RCC_ClkInitStruct.APB1CLKDivider = RCC_HCLK_DIV4;     /* 42 MHz */
    RCC_ClkInitStruct.APB2CLKDivider = RCC_HCLK_DIV2;     /* 84 MHz */
    (void)HAL_RCC_ClockConfig(&RCC_ClkInitStruct, FLASH_LATENCY_5);
}

/* ==================================================================
 *  Private: GPIO Initialisation
 * ================================================================== */

static void MX_GPIO_Init(void)
{
    GPIO_InitTypeDef GPIO_InitStruct = {0};

    /* Enable GPIO clocks */
    __HAL_RCC_GPIOA_CLK_ENABLE();
    __HAL_RCC_GPIOB_CLK_ENABLE();
    __HAL_RCC_GPIOD_CLK_ENABLE();
    __HAL_RCC_GPIOE_CLK_ENABLE();

    /* Motor direction pins: PB0 (IN1), PB1 (IN2) – push-pull output */
    GPIO_InitStruct.Pin   = GPIO_PIN_0 | GPIO_PIN_1;
    GPIO_InitStruct.Mode  = GPIO_MODE_OUTPUT_PP;
    GPIO_InitStruct.Pull  = GPIO_NOPULL;
    GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOB, &GPIO_InitStruct);
    HAL_GPIO_WritePin(GPIOB, GPIO_PIN_0 | GPIO_PIN_1, GPIO_PIN_RESET);

    /* LED pins: PD12, PD13, PD14, PD15 – push-pull output */
    GPIO_InitStruct.Pin   = GPIO_PIN_12 | GPIO_PIN_13 | GPIO_PIN_14 | GPIO_PIN_15;
    GPIO_InitStruct.Mode  = GPIO_MODE_OUTPUT_PP;
    GPIO_InitStruct.Pull  = GPIO_NOPULL;
    GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_LOW;
    HAL_GPIO_Init(GPIOD, &GPIO_InitStruct);
    HAL_GPIO_WritePin(GPIOD, GPIO_PIN_12 | GPIO_PIN_13 | GPIO_PIN_14 | GPIO_PIN_15, GPIO_PIN_RESET);

    /* LED pins: PE0, PE1 – push-pull output */
    GPIO_InitStruct.Pin   = GPIO_PIN_0 | GPIO_PIN_1;
    HAL_GPIO_Init(GPIOE, &GPIO_InitStruct);
    HAL_GPIO_WritePin(GPIOE, GPIO_PIN_0 | GPIO_PIN_1, GPIO_PIN_RESET);
}

/* ==================================================================
 *  Private: UART2 Initialisation
 * ================================================================== */

static void MX_USART2_UART_Init(void)
{
    /* Enable USART2 clock */
    __HAL_RCC_USART2_CLK_ENABLE();

    /* PA2 = TX, PA3 = RX – alternate function */
    GPIO_InitTypeDef GPIO_InitStruct = {0};
    GPIO_InitStruct.Pin       = GPIO_PIN_2 | GPIO_PIN_3;
    GPIO_InitStruct.Mode      = GPIO_MODE_AF_PP;
    GPIO_InitStruct.Pull      = GPIO_PULLUP;
    GPIO_InitStruct.Speed     = GPIO_SPEED_FREQ_VERY_HIGH;
    GPIO_InitStruct.Alternate = GPIO_AF7_USART2;
    HAL_GPIO_Init(GPIOA, &GPIO_InitStruct);

    huart2.Instance          = USART2;
    huart2.Init.BaudRate     = 115200U;
    huart2.Init.WordLength   = UART_WORDLENGTH_8B;
    huart2.Init.StopBits     = UART_STOPBITS_1;
    huart2.Init.Parity       = UART_PARITY_NONE;
    huart2.Init.Mode         = UART_MODE_TX_RX;
    huart2.Init.HwFlowCtl    = UART_HWCONTROL_NONE;
    huart2.Init.OverSampling = UART_OVERSAMPLING_16;
    (void)HAL_UART_Init(&huart2);
}

