/* ==================================================================
 *  Private: TIM2 PWM Initialisation (PA0, CH1)
 * ================================================================== */

static void MX_TIM2_Init(void)
{
    TIM_OC_InitTypeDef sConfigOC = {0};

    __HAL_RCC_TIM2_CLK_ENABLE();

    /* PA0 = TIM2_CH1 – alternate function */
    GPIO_InitTypeDef GPIO_InitStruct = {0};
    GPIO_InitStruct.Pin       = GPIO_PIN_0;
    GPIO_InitStruct.Mode      = GPIO_MODE_AF_PP;
    GPIO_InitStruct.Pull      = GPIO_NOPULL;
    GPIO_InitStruct.Speed     = GPIO_SPEED_FREQ_LOW;
    GPIO_InitStruct.Alternate = GPIO_AF1_TIM2;
    HAL_GPIO_Init(GPIOA, &GPIO_InitStruct);

    /*
     * PWM frequency placeholder:
     * Timer clock = APB1 × 2 = 84 MHz  (APB1 prescaler ≠ 1)
     * Prescaler = 83 → timer tick = 1 MHz
     * Period = 999 → PWM freq = 1 kHz
     * Duty default set by motor_driver (MOTOR_PWM_DUTY_DEFAULT = 699 → 70 %)
     */
    htim2.Instance               = TIM2;
    htim2.Init.Prescaler         = 83U;
    htim2.Init.CounterMode       = TIM_COUNTERMODE_UP;
    htim2.Init.Period            = 999U;
    htim2.Init.ClockDivision     = TIM_CLOCKDIVISION_DIV1;
    htim2.Init.AutoReloadPreload = TIM_AUTORELOAD_PRELOAD_ENABLE;
    (void)HAL_TIM_PWM_Init(&htim2);

    sConfigOC.OCMode     = TIM_OCMODE_PWM1;
    sConfigOC.Pulse      = 0U;   /* start with 0 % duty */
    sConfigOC.OCPolarity = TIM_OCPOLARITY_HIGH;
    sConfigOC.OCFastMode = TIM_OCFAST_DISABLE;
    (void)HAL_TIM_PWM_ConfigChannel(&htim2, &sConfigOC, TIM_CHANNEL_1);
}

/* ==================================================================
 *  Public API
 * ================================================================== */

/*
 * SWE-REQ-020 : initialise all device interfaces, ensure motor off
 * SWE-REQ-021 : read feedback and indicate initial state on LEDs
 */
void system_init(void)
{
    uint8_t init_pos   = 0U;
    bool    init_valid = false;

    /* --- HAL & clock --- */
    (void)HAL_Init();
    SystemClock_Config();

    /* --- Peripheral init --- */
    MX_GPIO_Init();
    MX_USART2_UART_Init();
    MX_ADC1_Init();
    MX_TIM2_Init();

    /* --- Software unit init (motor off first) --- */
    motor_driver_init();          /* Ensures motor is OFF [SWE-REQ-020] */
    command_parser_init();
    feedback_processor_init();
    flap_control_init();
    led_status_init();

    /* --- Power LED ON [SWE-REQ-012] --- */
    led_status_set_power();

    /* --- Read initial feedback and indicate [SWE-REQ-021] --- */
    feedback_processor_update();
    feedback_processor_get_position(&init_pos, &init_valid);

    if (init_valid)
    {
        led_status_set_position(init_pos);
    }
    else
    {
        led_status_indicate_error();
    }
}
